    memcpy(buf, tmp, (size_t)len + 1);
    return len;
}

long wt_kitchen(long grams) {
    long step;
    if (grams < 0) return -1;
    if (grams <= 100) return grams;
    step = grams <= 1000 ? 5 : 10;
    return (grams + step / 2) / step * step;
}

